+        let replacement = SignedBoardObject::sign(
+            &creator,
+            3,
+            "",
+            BoardObject::Tombstone(Tombstone {
+                board: root_hash.clone(),
+                target: reply_hash,
+                reason: Some("duplicate".to_owned()),
